import{_ as l,C as o,o as a,c as n,a2 as t,E as r}from"./chunks/framework.BSaF8iZ6.js";const S=JSON.parse('{"title":"Seller Management","description":"","frontmatter":{},"headers":[],"relativePath":"sellers/seller-management.md","filePath":"sellers/seller-management.md","lastUpdated":1789411447000}'),i={name:"sellers/seller-management.md"};function d(g,e,h,p,c,u){const s=o("ImagePopup");return a(),n("div",null,[e[0]||(e[0]=t('<h1 id="seller-management" tabindex="-1">Seller Management <a class="header-anchor" href="#seller-management" aria-label="Permalink to &quot;Seller Management&quot;">​</a></h1><div class="page-roles"><span class="role role--admin">Admin</span></div><p>As the admin, you approve new sellers, edit their details, set their commission and limits, and suspend or remove them when needed.</p><h2 id="the-sellers-list" tabindex="-1">The sellers list <a class="header-anchor" href="#the-sellers-list" aria-label="Permalink to &quot;The sellers list&quot;">​</a></h2><p>Go to <strong>Marketplace &gt;&gt; Sellers</strong>. The list shows every seller account, but not the team members sellers add to their shops.</p>',5)),r(s,{src:"/images/seller-management/admin-sellers-grid.png",alt:"The Sellers list in the admin panel"}),e[1]||(e[1]=t('<p>Each row shows:</p><ul><li><strong>Seller Name</strong> — the seller&#39;s name and email, a link to their shop page and the seller ID.</li><li><strong>Account Health</strong> — the health score and its band, the cancellation rate, the average rating, and a link to the seller&#39;s flags. See <a href="./seller-account-health">Account Health</a>.</li><li><strong>Status</strong> — <strong>Approved</strong> or <strong>Disapproved</strong>, <strong>Suspended</strong> when the account is suspended, and the date the seller joined.</li></ul><p>The icons at the end of a row are <strong>Assign Product</strong>, <strong>Login as Seller</strong>, <strong>Refresh Account Health</strong>, <strong>Edit</strong> and <strong>Delete</strong>.</p><p>Search by name or email, or use <strong>Filter</strong> to narrow the list by account health, status, suspension or joining date.</p><h2 id="approve-or-disapprove-sellers" tabindex="-1">Approve or disapprove sellers <a class="header-anchor" href="#approve-or-disapprove-sellers" aria-label="Permalink to &quot;Approve or disapprove sellers&quot;">​</a></h2><ol><li>Go to <strong>Marketplace &gt;&gt; Sellers</strong>.</li><li>Tick the sellers you want to change.</li><li>Click <strong>Select Action</strong>, point to <strong>Update Status</strong> and click <strong>Approved</strong> or <strong>Disapproved</strong>.</li><li>Click <strong>Agree</strong> to confirm.</li></ol>',6)),r(s,{src:"/images/seller-management/update-status.png",alt:"The Update Status bulk action with Approved and Disapproved"}),e[2]||(e[2]=t('<p>Each seller whose status changes receives a <strong>Seller Approval Notification</strong> email saying their request was accepted or rejected, and a <strong>Seller Profile Update Notification</strong> email.</p><p>A disapproved seller can&#39;t sign in, and their shop page is no longer available.</p><p>Whether new sellers need approval at all is set by <strong>Approval Required</strong> in <a href="./../configuration/sellers">Sellers settings</a>.</p><h2 id="add-a-seller" tabindex="-1">Add a seller <a class="header-anchor" href="#add-a-seller" aria-label="Permalink to &quot;Add a seller&quot;">​</a></h2><ol><li>Go to <strong>Marketplace &gt;&gt; Sellers</strong>.</li><li>Click <strong>Add Sellers</strong>.</li><li>In <strong>Create Seller</strong>, enter the <strong>Name</strong>, <strong>Email</strong>, <strong>Phone</strong> and <strong>Slug</strong>.</li><li>Enter a <strong>Password</strong> and <strong>Confirm Password</strong>.</li><li>Click <strong>Save</strong>. The seller&#39;s <strong>Edit Seller</strong> page opens so you can add the rest of their details.</li></ol>',5)),r(s,{src:"/images/seller-management/create-seller.png",alt:"The Create Seller form"}),e[3]||(e[3]=t('<p>The new seller follows the same approval rule and receives the same emails as a seller who signs up on the storefront.</p><h2 id="edit-a-seller" tabindex="-1">Edit a seller <a class="header-anchor" href="#edit-a-seller" aria-label="Permalink to &quot;Edit a seller&quot;">​</a></h2><ol><li>Go to <strong>Marketplace &gt;&gt; Sellers</strong>.</li><li>Click the edit icon on the seller&#39;s row.</li><li>Change the details you need.</li><li>Click <strong>Save Seller</strong>.</li></ol>',3)),r(s,{src:"/images/seller-management/admin-seller-edit.png",alt:"The Edit Seller page"}),e[4]||(e[4]=t('<p>The page has the seller&#39;s banner and logo at the top, then the cards you arrange in <a href="./seller-attributes">Seller Attributes</a>: <strong>General</strong>, <strong>Description</strong>, <strong>Policies</strong>, <strong>Meta Description</strong>, <strong>Address</strong>, <strong>Social Links</strong> and <strong>Settings</strong>. Use the menu on the banner or logo to upload a new image or delete it. A banner in a 3:1 ratio, around 1320×300 pixels, fits best.</p><p>The seller receives a <strong>Seller Profile Update Notification</strong> email each time you save.</p><h3 id="settings-for-this-seller" tabindex="-1">Settings for this seller <a class="header-anchor" href="#settings-for-this-seller" aria-label="Permalink to &quot;Settings for this seller&quot;">​</a></h3><p>The <strong>Settings</strong> card holds the details only you can change:</p>',4)),r(s,{src:"/images/seller-management/seller-settings.png",alt:"The Settings card on the Edit Seller page"}),e[5]||(e[5]=t('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Suspended</strong></td><td>Suspends the seller. See <a href="#suspend-a-seller">Suspend a seller</a>.</td></tr><tr><td><strong>Commission Enabled</strong></td><td>Gives this seller their own commission rate instead of the store&#39;s rate.</td></tr><tr><td><strong>Commission Percentage</strong></td><td>The seller&#39;s own rate, from 0 to 100. Required when <strong>Commission Enabled</strong> is on.</td></tr><tr><td><strong>Minimum Order Amount</strong></td><td>The least a customer must spend with this seller in one order. It appears when <strong>Enable Minimum Order Amount</strong> is on in <a href="./../configuration/sellers">Sellers settings</a>.</td></tr><tr><td><strong>Google Analytics ID</strong></td><td>Adds the seller&#39;s Google Analytics tracking to their shop page.</td></tr><tr><td><strong>Allowed Product Types</strong></td><td>The product types this seller can create and sell.</td></tr><tr><td><strong>Magic AI Enabled</strong></td><td>Lets this seller use Generative AI. See <a href="./../generative-ai/usage-limits">Usage Limits</a>.</td></tr><tr><td><strong>Magic AI Generation Limit</strong></td><td>This seller&#39;s own Generative AI limit. Leave it empty to use the store&#39;s limit, or enter 0 to block it.</td></tr></tbody></table><h3 id="the-other-cards" tabindex="-1">The other cards <a class="header-anchor" href="#the-other-cards" aria-label="Permalink to &quot;The other cards&quot;">​</a></h3><ul><li><strong>Channel</strong> — the channels the seller sells on. It appears when your store has more than one channel.</li><li><strong>Users</strong> — the team members the seller has added. It appears once there are any.</li><li><strong>Restricted Categories</strong> — categories this seller can&#39;t use for their products.</li><li><strong>Seller Sales</strong>, <strong>Discount</strong>, <strong>Commission</strong> and <strong>Seller Earnings</strong> — read-only totals for the seller, including how much has been invoiced and paid.</li></ul><h2 id="suspend-a-seller" tabindex="-1">Suspend a seller <a class="header-anchor" href="#suspend-a-seller" aria-label="Permalink to &quot;Suspend a seller&quot;">​</a></h2><ol><li>Open the seller&#39;s <strong>Edit Seller</strong> page.</li><li>In <strong>Settings</strong>, switch <strong>Suspended</strong> on.</li><li>Click <strong>Save Seller</strong>.</li></ol><p>A suspended seller is signed out of the Seller Panel with the message <strong>Your account has been suspended. Contact to admin for any query.</strong> Their shop page is no longer available and they are left out of the featured sellers. Switch <strong>Suspended</strong> off to restore the account.</p><h2 id="sign-in-as-a-seller" tabindex="-1">Sign in as a seller <a class="header-anchor" href="#sign-in-as-a-seller" aria-label="Permalink to &quot;Sign in as a seller&quot;">​</a></h2><p>Click the <strong>Login as Seller</strong> icon on the seller&#39;s row. The Seller Panel opens in a new tab, signed in as that seller, so you can see exactly what they see or help them set up.</p><h2 id="assign-a-product-to-a-seller" tabindex="-1">Assign a product to a seller <a class="header-anchor" href="#assign-a-product-to-a-seller" aria-label="Permalink to &quot;Assign a product to a seller&quot;">​</a></h2><p>You can list a catalog product for a seller, at the seller&#39;s own price and stock:</p><ol><li>Click the <strong>Assign Product</strong> icon on the seller&#39;s row.</li><li>Search for the product and choose it.</li><li>On <strong>Assign Product</strong>, choose the <strong>Condition</strong>, and enter the <strong>Price</strong>, <strong>Quantities</strong> and <strong>Description</strong>.</li><li>Click <strong>Save</strong>.</li></ol><p>The seller&#39;s profile must be complete first. See <a href="./../catalog/selling-existing-products">Selling Existing Products</a> for how the offer works.</p><h2 id="delete-a-seller" tabindex="-1">Delete a seller <a class="header-anchor" href="#delete-a-seller" aria-label="Permalink to &quot;Delete a seller&quot;">​</a></h2><p>Click the delete icon on the seller&#39;s row, or tick several sellers and use <strong>Select Action &gt;&gt; Delete</strong>.</p><p>A seller who still has pending or processing orders can&#39;t be deleted. You&#39;ll see <strong>Seller has some pending orders</strong>. When a seller is deleted, their files and stock records are removed and they receive a <strong>Seller Good Bye Notification</strong> email.</p><h2 id="seller-statuses" tabindex="-1">Seller statuses <a class="header-anchor" href="#seller-statuses" aria-label="Permalink to &quot;Seller statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>How it is set</th><th>What the seller can do</th></tr></thead><tbody><tr><td><strong>Approved</strong></td><td>You approve the seller, or approval isn&#39;t required</td><td>Sign in and sell. Their shop page is public when <strong>Show Publicly</strong> is on.</td></tr><tr><td><strong>Disapproved</strong></td><td>New sellers when approval is required, or you disapprove them</td><td>Can&#39;t sign in. Their shop page isn&#39;t available.</td></tr><tr><td><strong>Suspended</strong></td><td>You switch <strong>Suspended</strong> on</td><td>Signed out and can&#39;t use the Seller Panel. Their shop page isn&#39;t available.</td></tr></tbody></table><h2 id="seller-emails" tabindex="-1">Seller emails <a class="header-anchor" href="#seller-emails" aria-label="Permalink to &quot;Seller emails&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Email</th><th>Sent to</th><th>When</th></tr></thead><tbody><tr><td><strong>New Seller Registration</strong></td><td>Store admin</td><td>A seller signs up or you add one</td></tr><tr><td><strong>Seller Welcome Notification</strong></td><td>Seller</td><td>A seller signs up or you add one</td></tr><tr><td><strong>Seller Approval Notification</strong></td><td>Seller</td><td>The seller is approved or disapproved, or is created already approved</td></tr><tr><td><strong>Seller Profile Update Notification</strong></td><td>Seller</td><td>The seller&#39;s details or status are saved, by you or by the seller</td></tr><tr><td><strong>Seller Good Bye Notification</strong></td><td>Seller</td><td>The seller is deleted</td></tr></tbody></table><p>The admin email goes to the address in the store&#39;s email settings.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>To give another admin access, tick <strong>Marketplace &gt;&gt; Sellers &gt;&gt; Sellers</strong> in their role, along with <strong>Create</strong>, <strong>Edit</strong>, <strong>Delete</strong>, <strong>Assign Product</strong> and <strong>Refresh Account Health</strong> as needed.</p>',22))])}const f=l(i,[["render",d]]);export{S as __pageData,f as default};
